import b200probe as bp, torch, time, statistics as st
from cuda.bindings import driver as drv
SRC = r'''
#define LD4(p, v) asm volatile("ld.global.nc.v4.f32 {%0,%1,%2,%3}, [%4];" : "=f"(v[0]),"=f"(v[1]),"=f"(v[2]),"=f"(v[3]) : "l"(p))
#define LDX4(p, v) asm volatile("ld.global.nc.L1::no_allocate.v4.f32 {%0,%1,%2,%3}, [%4];" : "=f"(v[0]),"=f"(v[1]),"=f"(v[2]),"=f"(v[3]) : "l"(p))
#define ST4EL(p, v, pol) asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%2,%3,%4}, %5;" :: "l"(p), "f"(v[0]),"f"(v[1]),"f"(v[2]),"f"(v[3]), "l"(pol) : "memory")
__device__ __forceinline__ unsigned div_magic(unsigned n, unsigned m, unsigned l){ return (__umulhi(n, m) + n) >> l; }
// MODE 0 full, 1 loads only, 2 stores only
template <int THREADS, int MODE>
__device__ __forceinline__ void rope_row(const float* q, const float* k, const float* cs, const float* sn, float* qo, float* ko,
         unsigned Rq, unsigned R, unsigned S, unsigned m, unsigned l)
{
    constexpr int ROWS = THREADS / 16;
    const unsigned j = threadIdx.x & 15;
    const unsigned r = blockIdx.x * ROWS + (threadIdx.x >> 4);
    if (r >= R) return;
    const float* x; float* y; unsigned rl;
    if (r < Rq) { x = q; y = qo; rl = r; } else { x = k; y = ko; rl = r - Rq; }
    const unsigned s = rl - div_magic(rl, m, l) * S;
    const float* xp = x + (size_t)rl * 128 + j * 4;
    const float* cp = cs + (size_t)s * 128 + j * 4;
    const float* sp = sn + (size_t)s * 128 + j * 4;
    y += (size_t)rl * 128 + j * 4;
    float xl[4], xh[4], cl[4], ch[4], sl[4], sh[4], ol[4], oh[4];
    unsigned long long pol;
    asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pol));
    if (MODE == 2) {
        for (int e=0;e<4;++e){ ol[e]=(float)e; oh[e]=(float)j; }
        ST4EL(y, ol, pol); ST4EL(y + 64, oh, pol); return;
    }
    LDX4(xp, xl); LDX4(xp + 64, xh);
    LD4(cp, cl);  LD4(cp + 64, ch);
    LD4(sp, sl);  LD4(sp + 64, sh);
    for (int e = 0; e < 4; ++e) {
        ol[e] = xl[e] * cl[e] - xh[e] * sl[e];
        oh[e] = xh[e] * ch[e] + xl[e] * sh[e];
    }
    if (MODE == 1) {
        float a = 0; for (int e=0;e<4;++e) a += ol[e]+oh[e];
        if (a == 1.2345e-30f) ST4EL(y, ol, pol);
        return;
    }
    ST4EL(y, ol, pol); ST4EL(y + 64, oh, pol);
}
template <int THREADS, int MODE>
__device__ __forceinline__ void rope_pair(const float* q, const float* k, const float* cs, const float* sn, float* qo, float* ko,
          unsigned Pq, unsigned P, unsigned S, unsigned m, unsigned l)
{
    constexpr int PAIRS = THREADS / 16;
    const unsigned j = threadIdx.x & 15;
    const unsigned p = blockIdx.x * PAIRS + (threadIdx.x >> 4);
    if (p >= P) return;
    const float* x; float* y; unsigned pl;
    if (p < Pq) { x = q; y = qo; pl = p; } else { x = k; y = ko; pl = p - Pq; }
    const unsigned qd = div_magic(pl, m, l);
    const unsigned s = pl - qd * S;
    const size_t row0 = (size_t)(2 * qd) * S + s;
    const size_t hs = (size_t)S * 128;
    const float* xp = x + row0 * 128 + j * 4;
    const float* cp = cs + (size_t)s * 128 + j * 4;
    const float* sp = sn + (size_t)s * 128 + j * 4;
    y += row0 * 128 + j * 4;
    float xl0[4], xh0[4], xl1[4], xh1[4], cl[4], ch[4], sl[4], sh[4], ol[4], oh[4];
    unsigned long long pol;
    asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pol));
    if (MODE == 2) {
        for (int e=0;e<4;++e){ ol[e]=(float)e; oh[e]=(float)j; }
        ST4EL(y, ol, pol); ST4EL(y + 64, oh, pol); ST4EL(y + hs, ol, pol); ST4EL(y + hs + 64, oh, pol); return;
    }
    LDX4(xp, xl0);      LDX4(xp + 64, xh0);
    LDX4(xp + hs, xl1); LDX4(xp + hs + 64, xh1);
    LD4(cp, cl);  LD4(cp + 64, ch);
    LD4(sp, sl);  LD4(sp + 64, sh);
    if (MODE == 1) {
        float a = 0;
        for (int e=0;e<4;++e) a += xl0[e]*cl[e]-xh0[e]*sl[e] + xh0[e]*ch[e]+xl0[e]*sh[e] + xl1[e]*cl[e]-xh1[e]*sl[e] + xh1[e]*ch[e]+xl1[e]*sh[e];
        if (a == 1.2345e-30f) ST4EL(y, ol, pol);
        return;
    }
    for (int e = 0; e < 4; ++e) { ol[e] = xl0[e] * cl[e] - xh0[e] * sl[e]; oh[e] = xh0[e] * ch[e] + xl0[e] * sh[e]; }
    ST4EL(y, ol, pol); ST4EL(y + 64, oh, pol);
    for (int e = 0; e < 4; ++e) { ol[e] = xl1[e] * cl[e] - xh1[e] * sl[e]; oh[e] = xh1[e] * ch[e] + xl1[e] * sh[e]; }
    ST4EL(y + hs, ol, pol); ST4EL(y + hs + 64, oh, pol);
}
#define ARGS const float* q, const float* k, const float* cs, const float* sn, float* qo, float* ko, unsigned a, unsigned b, unsigned S, unsigned m, unsigned l
#define CALL q,k,cs,sn,qo,ko,a,b,S,m,l
extern "C" {
__global__ void __launch_bounds__(128) row128(ARGS){ rope_row<128,0>(CALL); }
__global__ void __launch_bounds__(128) pair128(ARGS){ rope_pair<128,0>(CALL); }
__global__ void __launch_bounds__(64) pair64(ARGS){ rope_pair<64,0>(CALL); }
__global__ void __launch_bounds__(64) row64(ARGS){ rope_row<64,0>(CALL); }
__global__ void __launch_bounds__(128) row128_ld(ARGS){ rope_row<128,1>(CALL); }
__global__ void __launch_bounds__(128) row128_st(ARGS){ rope_row<128,2>(CALL); }
__global__ void __launch_bounds__(128) pair128_ld(ARGS){ rope_pair<128,1>(CALL); }
__global__ void __launch_bounds__(128) pair128_st(ARGS){ rope_pair<128,2>(CALL); }
__global__ void __launch_bounds__(128) empty128(ARGS){ }
}
'''
def K(name): return bp.cuda_kernel(SRC, name)
def carve(k, pct):
    r = drv.cuFuncSetAttribute(k.fn, drv.CUfunction_attribute.CU_FUNC_ATTRIBUTE_PREFERRED_SHARED_MEMORY_CARVEOUT, pct); return r
def magic(S):
    l=0
    while (1<<l)<S: l+=1
    m=(((1<<32)*((1<<l)-S))//S)+1
    if m>=2**31: m-=2**32
    return m,l
def mkargs(B,H,Hkv,S):
    dev='cuda'
    q=torch.randn(B,H,S,128,device=dev); k=torch.randn(B,Hkv,S,128,device=dev)
    c=torch.cos(torch.randn(S,128,device=dev).clamp(-2,2)); s=torch.sin(torch.randn(S,128,device=dev).clamp(-2,2))
    qo=torch.zeros_like(q); ko=torch.zeros_like(k)
    return q,k,c,s,qo,ko
def ref(q,k,c,s):
    def rh(x): return torch.cat((-x[...,64:],x[...,:64]),-1)
    return q*c+rh(q)*s, k*c+rh(k)*s
def variant(kind, kern, B,H,Hkv,S, smem=0):
    Rq=B*H*S; R=Rq+B*Hkv*S; m,l=magic(S)
    if kind=='row':
        T=kern.T; grid=(R+T//16-1)//(T//16); a,b=Rq,R
    else:
        T=kern.T; per=T//16; P=R//2; grid=(P+per-1)//per; a,b=Rq//2,P
    def fn(q,k,c,s,qo,ko):
        kern(grid,(T,),q,k,c,s,qo,ko,a,b,S,m,l,smem=smem)
    return fn
def mk(name,T,pct=None):
    k=K(name); k.T=T
    if pct is not None: print('carve',name,pct,carve(k,pct))
    return k
shapes={'2.2MB':(1,8,8,128),'6.6MB':(1,40,8,131),'15.8MB':(2,32,4,211),'134MB':(64,8,8,128)}
vars_={}
vars_['pairP128']=('pair',mk('pair128',128,50),11500)
vars_['pairU128']=('pair',mk('pair128',128),0)
vars_['row128']=('row',mk('row128',128),0)
vars_['pair64']=('pair',mk('pair64',64),0)
vars_['row64']=('row',mk('row64',64),0)
res={}
for sn,sh in shapes.items():
    args=mkargs(*sh)
    rq,rk=ref(*args[:4])
    fns={}
    for vn,(kind,kern,smem) in vars_.items():
        fn=variant(kind,kern,*sh,smem=smem)
        args[4].zero_(); args[5].zero_(); fn(*args); torch.cuda.synchronize()
        ok=(args[4]-rq).abs().max().item()<1e-5 and (args[5]-rk).abs().max().item()<1e-5
        if not ok: print('WRONG',sn,vn)
        fns[vn]=fn
    t={vn:[] for vn in fns}
    for rep in range(3):
        for vn,fn in fns.items():
            t[vn].append(bp.harness_time(fn,args[:4],args[4:]))
    res[sn]=t
    print(sn,{vn:[round(x,2) for x in v] for vn,v in t.items()},flush=True)

